CREATE ROW ACCESS POLICY IF NOT EXISTS SEC.RAP_REGION AS (p_region STRING) RETURNS BOOLEAN -> TRUE
  COMMENT = 'From Cognos securityFilter RegionFilter on Location; applies to Regional_Analysts, Operations_Viewers, Billing_Analysts; exempt Report_Admins, Data_Engineers, Executive_Viewers';

ALTER ROW ACCESS POLICY SEC.RAP_REGION SET BODY ->
    IS_ROLE_IN_SESSION('DATA_ENGINEERS') OR IS_ROLE_IN_SESSION('EXECUTIVE_VIEWERS') OR IS_ROLE_IN_SESSION('REPORT_ADMINS')
    OR p_region IN (SELECT m.REGION FROM SEC.MAP_USER_REGION m WHERE m.USERNAME = CURRENT_USER());

ALTER ROW ACCESS POLICY SEC.RAP_REGION SET COMMENT = 'From Cognos securityFilter RegionFilter on Location; applies to Regional_Analysts, Operations_Viewers, Billing_Analysts; exempt Report_Admins, Data_Engineers, Executive_Viewers';
